+  // Mixed: host, port, query, group, key — all preserved.
+  const full = Services.io.newURI(
+    "news://news.example:563/msg%40id?group=comp.test&key=42"
+  );
+  Assert.equal(
+    full.spec,
+    "news://news.example:563/msg%40id?group=comp.test&key=42"
+  );
+  Assert.equal(full.host, "news.example");
+  Assert.equal(full.port, 563);
